command -v visudo >/dev/null 2>&1 || exit 0
for f in /etc/sudoers $(ls /etc/sudoers.d/* 2>/dev/null); do
  [ -f "$f" ] || continue
  grep -Eq 'timestamp_timeout[[:space:]]*=[[:space:]]*(-|1[6-9]|[2-9][0-9]|[0-9]{3,})' "$f" || continue
  t=$(mktemp); cp -a "$f" "$t"
  sed -i -E 's/(timestamp_timeout[[:space:]]*=[[:space:]]*)(-[0-9.]*|1[6-9][0-9.]*|[2-9][0-9][0-9.]*|[0-9]{3,}[0-9.]*)/\115/' "$t"
  if visudo -cf "$t" >/dev/null 2>&1; then tma_bak "$f"; cat "$t" > "$f"; fi
  rm -f "$t"
done
grep -rqE '^[[:space:]]*Defaults[[:space:]].*timestamp_timeout' /etc/sudoers /etc/sudoers.d 2>/dev/null || {
  t=$(mktemp); echo 'Defaults timestamp_timeout=15' > "$t"
  if visudo -cf "$t" >/dev/null 2>&1; then umask 077; cp "$t" /etc/sudoers.d/00-tmaegis-timeout; chmod 440 /etc/sudoers.d/00-tmaegis-timeout; fi
  rm -f "$t"; }
true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
