PAMF="/etc/pam.d/system-auth /etc/pam.d/password-auth /etc/pam.d/system-password /etc/pam.d/common-auth /etc/pam.d/common-password /etc/pam.d/common-account /etc/pam.d/common-session /etc/pam.d/common-session-noninteractive /etc/pam.d/postlogin"
# tma_pam_sed EXPR : sed -E on every existing PAM stack file (follows symlinks, backs up once)
tma_pam_sed() { for f in $PAMF /usr/share/pam-configs/unix; do
  [ -e "$f" ] || continue; tma_bak "$f"; sed -i --follow-symlinks -E "$1" "$f"; done; }
# tma_conf_set FILE KEY VALUE : "key = value", replacing active or commented key lines
tma_conf_set() { f=$1; k=$2; v=$3; mkdir -p "$(dirname "$f")"; [ -e "$f" ] || : > "$f"; tma_bak "$f"
  sed -i -E "/^[[:space:]]*#?[[:space:]]*$k[[:space:]]*=/d" "$f"; printf '%s = %s\n' "$k" "$v" >> "$f"; }
tma_conf_del() { for f in $2; do [ -e "$f" ] || continue; tma_bak "$f"; sed -i -E "/^[[:space:]]*$1[[:space:]]*=/d" "$f"; done; }
# keep yescrypt where present, otherwise force sha512 on password lines
tma_pam_sed '/^[[:space:]]*password[[:space:]].*pam_unix\.so/ { /(sha512|yescrypt)/! { s/[[:space:]]+(md5|bigcrypt|blowfish|sha256|des)\b//g; s/$/ sha512/ } }'
if [ -f /etc/login.defs ]; then tma_bak /etc/login.defs
  grep -Eqi '^[[:space:]]*ENCRYPT_METHOD[[:space:]]+(SHA512|YESCRYPT)\b' /etc/login.defs || {
    sed -i -E '/^[[:space:]]*ENCRYPT_METHOD[[:space:]]/d' /etc/login.defs; echo 'ENCRYPT_METHOD SHA512' >> /etc/login.defs; }
fi
if [ -f /etc/libuser.conf ]; then tma_bak /etc/libuser.conf; sed -i -E 's/^[[:space:]]*crypt_style[[:space:]]*=.*/crypt_style = sha512/' /etc/libuser.conf; fi
