    n=${kv%% *}
    for f in $files; do
      [ -L "$f" ] && continue
      sed -i -E "s/^([[:space:]]*$n[[:space:]=].*)$/# tmaegis: \1/I" "$f"
    done
  done
  tmp=$(mktemp); : > "$tmp"
  for kv in "$@"; do printf '%s\n' "$kv" >> "$tmp"; done
  cat "$c" >> "$tmp"; cat "$tmp" > "$c"; rm -f "$tmp"
  if command -v sshd >/dev/null 2>&1 && ! sshd -t 2>/dev/null; then
    echo "sshd -t failed, restoring" >&2
    for f in $files; do cat "$sv/$(echo "$f" | tr / _)" > "$f"; done
    rm -rf "$sv"; return 1
  fi
  rm -rf "$sv"
  for u in sshd ssh; do systemctl reload "$u" 2>/dev/null && break; done
  return 0
