# mirrors the CIS per-file policy: mask = mode bits to strip; users/groups = accepted owners
find -L /var/log -type f \( -perm /0137 -o ! -user root -o ! -group root \) 2>/dev/null | while IFS= read -r f; do
  mode=$(stat -Lc %a "$f"); u=$(stat -Lc %U "$f"); g=$(stat -Lc %G "$f"); b=${f##*/}; dir=$(dirname "$f")
  mask=137; au=" root syslog "; ag=" root adm "
  case "$dir" in */apt) mask=133; au=" root "; ag=" root adm "; b="";; esac
  case "$b" in
    lastlog|lastlog.*|wtmp|wtmp.*|wtmp-*|btmp|btmp.*|btmp-*|README) mask=113; au=" root "; ag=" root utmp ";;
    SSSD|sssd) mask=117; au=" root SSSD "; ag=" root SSSD ";;
    gdm|gdm3) mask=117; au=" root "; ag=" root gdm gdm3 ";;
    *.journal|*.journal~) mask=137; au=" root "; ag=" root systemd-journal ";;
    cloud-init.log*|localmessages*|waagent.log*) mask=133;;
    secure|secure.*|secure-*|auth.log|syslog|messages) mask=137;;
    *) # service accounts without a login shell may own their own logs
       sh=$(awk -F: -v u="$u" '$1==u{print $7}' /etc/passwd)
       if [ "$u" = root ] || ! grep -Fxq -- "$sh" /etc/shells 2>/dev/null; then
         case "$au" in *" $u "*) ;; *) au="$au$u ";; esac
         case "$ag" in *" $g "*) ;; *) ag="$ag$g ";; esac
       fi;;
  esac
  [ $((8#$mode & 8#$mask)) -eq 0 ] || chmod "$(printf '%o' $((8#$mode & ~8#$mask & 8#7777)))" "$f"
  case "$au" in *" $u "*) ;; *) chown root "$f";; esac
  case "$ag" in *" $g "*) ;; *) chgrp root "$f";; esac
done
